//! 🎟️ Genuine original lifetime claims preserve quantum-one work and separately paid return receipts.
use semio_framework_job_context::testkit;
use super::*;
use crate::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_diagnostic::FaultMessageOwner;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress as P};
use serde_json::Value;
fn clock()->Option<u64>{Some(0)}
#[test]
fn actual_source_holds_leave_real_quantum_one_usable_and_never_reissue_return_credit(){
 let law:Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let source=&law["source"];let stock=RetainedCloneGrant{maximum_items:source["items"].as_u64().unwrap()as usize,maximum_copy_bytes:source["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:source["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:source["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:source["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..stock};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7519),Generation(7),stock,clock,source["deadlineUs"].as_u64().unwrap(),source["fuel"].as_u64().unwrap());let mut loan=None;let mut held=None;let mut body=None;let mut pointer=0;
 caller.turn(q,|cx|{assert!(cx.original_source_parent()?.admit_loan(&mut loan,cx)?);assert!(loan.is_some());Ok(())}).unwrap();
 caller.turn(q,|cx|{assert!(testkit::admit_return_origin(cx)?);Ok(())}).unwrap();
 for axis in ["items","depth"]{let mut denied=q;if axis=="items"{denied.maximum_items=0}else{denied.maximum_depth=0}caller.turn(denied,|cx|{let before=testkit::return_budget_snapshot(cx);let fuel=cx.fuel_remaining();let receipt=cx.retained_progress();let(result,h)=observe(||claim_original_return(cx,&mut held));assert!(!result?);assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(testkit::return_budget_snapshot(cx),before);assert_eq!(cx.fuel_remaining(),fuel);assert_eq!(cx.retained_progress(),receipt);Ok(())}).unwrap();}
 caller.turn(q,|cx|{let phase=RetainedCloneGrant{maximum_items:0,..cx.retained_grant()};cx.bind_original_retained_total(phase)?;let before=testkit::return_budget_snapshot(cx);assert_eq!(cx.original_total_retained_grant().maximum_items,0);assert!(!claim_original_return(cx,&mut held)?);assert_eq!(testkit::return_budget_snapshot(cx),before);Ok(())}).unwrap();
 caller.turn(q,|cx|{assert!(claim_original_return(cx,&mut held)?);assert!(held.is_some());let s=testkit::return_budget_snapshot(cx);assert_eq!((s.held_items,s.held_fuel),(2,2));assert!(s.conserved());Ok(())}).unwrap();
 caller.turn(q,|cx|{let before=testkit::return_budget_snapshot(cx);let receipt=cx.retained_progress();let cpu=cx.original_work_units_spent();let identity=testkit::original_return_source::OriginalReturnBodyIdentity::capture(cx);let(result,heap)=observe(||testkit::original_return_source::qualify_original_return_credit(held.as_ref().unwrap(),cx,&identity));result?;assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let operation=cx.operation();*testkit::operation_mut(cx)=OperationId(operation.0+1);let result=testkit::original_return_source::qualify_original_return_credit(held.as_ref().unwrap(),cx,&identity);*testkit::operation_mut(cx)=operation;assert!(result.is_err());assert_eq!(testkit::return_budget_snapshot(cx),before);assert_eq!(cx.retained_progress(),receipt);assert_eq!(cx.original_work_units_spent(),cpu);Ok(())}).unwrap();
 caller.turn(q,|cx|{
  let deadline=cx.original_absolute_deadline_us();cx.with_original_work_loan(1,deadline,|same|{assert_eq!(same.retained_grant().maximum_items,1);assert_eq!(same.fuel_remaining(),1);let(turn,h)=observe(||FaultMessageOwner::construct("Original quantum one 源",same.retained_grant()));let work=turn.work;let(owner,p)=turn.result?;assert!(owner.ready());pointer=owner.fault().unwrap().message.as_ptr()as usize;assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));same.consume_retained(p)?;same.consume_fuel(work);assert_eq!(same.retained_grant().maximum_items,0);assert_eq!(same.fuel_remaining(),0);body=Some(owner);Ok(())})?;
  let raw_fuel=cx.original_source_fuel_remaining();let spendable=cx.fuel_remaining();cx.with_original_work_loan(0,cx.original_absolute_deadline_us(),|cx|{assert_eq!(cx.fuel_remaining(),0);
  let before=cx.retained_progress();let work=cx.original_work_units_spent();assert!(testkit::return_source_is_borrowed(cx.original_source_parent()?)?);let bank=testkit::return_budget_snapshot(cx);let credit=held.as_mut().unwrap();let(witness,h)=observe(||credit.issue_return(OriginalReturnPhase::Capture,0));let mut witness=Some(witness?);assert_eq!(testkit::return_budget_snapshot(cx),bank);assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));let operation=cx.operation();*testkit::operation_mut(cx)=OperationId(operation.0+1);let denied_before=cx.retained_progress();let denied_work=cx.original_work_units_spent();let(result,heap)=observe(||receive_original_return_witness(cx,credit,&mut witness));*testkit::operation_mut(cx)=operation;assert!(result.is_err());assert!(witness.is_some());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),denied_before);assert_eq!(cx.original_work_units_spent(),denied_work);let original=cx.retained_progress();testkit::retained_progress_mut(cx).copied_items=usize::MAX;let bank=testkit::return_budget_snapshot(cx);let result=receive_original_return_witness(cx,credit,&mut witness);*testkit::retained_progress_mut(cx)=original;assert!(result.is_err());assert!(witness.is_some());assert_eq!(testkit::return_budget_snapshot(cx),bank);receive_original_return_witness(cx,credit,&mut witness)?;assert_eq!(cx.reserved_return_progress(),P{copied_items:1,..Default::default()});assert_eq!(cx.retained_progress().copied_items,before.copied_items+1);assert_eq!(cx.original_work_units_spent()-work,1);assert_eq!(body.as_ref().unwrap().fault().unwrap().message.as_ptr()as usize,pointer);
  let(witness,h)=observe(||credit.issue_return(OriginalReturnPhase::Receive,0));let mut witness=Some(witness?);receive_original_return_witness(cx,credit,&mut witness)?;assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));let s=testkit::return_budget_snapshot(cx);assert!(s.conserved());assert_eq!((s.held_items,s.held_fuel),(0,0));let before=s;assert!(credit.issue_return(OriginalReturnPhase::Receive,0).is_err());assert_eq!(testkit::return_budget_snapshot(cx),before);assert_eq!(cx.reserved_return_progress(),P{copied_items:2,..Default::default()});assert_eq!(cx.reserved_return_work(),2);assert!(credit.terminal_is_empty());assert_eq!(cx.fuel_remaining(),0);Ok(())})?;assert_eq!(cx.original_source_fuel_remaining()+2,raw_fuel);assert_eq!(cx.fuel_remaining(),spendable);Ok(())
 }).unwrap();
 caller.turn(q,|cx|{drop(held.take());assert!(claim_original_return(cx,&mut held)?);Ok(())}).unwrap();
 caller.turn(q,|cx|{let before=testkit::return_budget_snapshot(cx);let spendable=cx.original_total_fuel_remaining();let raw=cx.original_source_fuel_remaining();let before_receipt=cx.retained_progress();cx.with_original_work_loan(0,cx.original_absolute_deadline_us(),|cx|{let(turn,h)=observe(||held.as_mut().unwrap().issue_success_return(0));let mut witness=Some(turn?);receive_original_return_witness(cx,held.as_mut().unwrap(),&mut witness)?;assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(cx.fuel_remaining(),0);Ok(())})?;let after=testkit::return_budget_snapshot(cx);assert!(after.conserved());assert_eq!((before.held_items,before.held_fuel),(2,2));assert_eq!((after.held_items,after.held_fuel,after.claims),(0,0,0));assert_eq!(after.spent.copied_items,before.spent.copied_items+1);assert_eq!(after.work,before.work+1);assert_eq!(cx.retained_progress().copied_items,before_receipt.copied_items+1);assert_eq!(cx.original_total_fuel_remaining(),spendable);assert_eq!(cx.original_source_fuel_remaining()+1,raw);assert!(held.as_ref().unwrap().terminal_is_empty());Ok(())}).unwrap();
 caller.turn(stock,|cx|{crate::original_failure_test_support::close(body.take(),cx,4096);let parent=cx.original_source_parent()?;for _ in 0..4096{if loan.as_ref().unwrap().terminal_is_empty(){break}loan.as_mut().unwrap().close_step(parent,cx)?;}assert!(loan.as_ref().unwrap().terminal_is_empty());Ok(())}).unwrap();drop(held);drop(loan);caller.retire(stock);
}

#[test]
fn actual_native_receiving_posts_the_same_source_span_once_before_semantic_settlement(){let mut shared_allocation_frame=semio_framework_value::native_decoding::NativeSharedAdmission::default();
 let corpus:Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let source=&corpus["source"];let stock=RetainedCloneGrant{maximum_items:source["items"].as_u64().unwrap()as usize,maximum_copy_bytes:source["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:source["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:source["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:source["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..stock};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7520),Generation(7),stock,clock,source["deadlineUs"].as_u64().unwrap(),source["fuel"].as_u64().unwrap());caller.turn(q,|cx|{assert!(testkit::admit_return_origin(cx)?);Ok(())}).unwrap();let expected=corpus["nativeConstruction"]["text"].as_str().unwrap();let mut input=Some(expected.to_owned());let mut output=None;let mut decoder=crate::OriginalJobDecodeOwner::empty();
 caller.turn_with_decoder(q,&mut decoder,|cx|{let before=testkit::return_budget_snapshot(cx);let(turn,heap)=observe(||cx.with_native_receiving::<_,semio_framework_value::ValueError>(|control|Ok(control.receive_shared(&mut input,&mut output,semio_framework_value::shared_issuance::SharedIssuer::owned(),&mut shared_allocation_frame))));let turn=turn?;cx.consume_fuel(turn.work);let p=turn.result.map_err(|primary|crate::OriginalTurnFailure::from(crate::OriginalTurnPrimary::Receiving(primary)))?;assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));let posted=testkit::return_budget_snapshot(cx);assert_eq!(posted.spent,before.spent.checked_add(p)?);assert_eq!(posted.work,before.work+u128::from(turn.work));assert_eq!(cx.receiving_child_progress(),p);cx.consume_receiving_retained(cx.receiving_issued_grant().unwrap(),p)?;assert_eq!(testkit::return_budget_snapshot(cx),posted);assert_eq!(serde_json::to_value(output.as_ref().unwrap().get()).unwrap(),corpus["nativeConstruction"]["text"]);Ok(())}).unwrap();
 caller.turn(stock,|cx|{crate::original_failure_test_support::close(output.take(),cx,4096);for _ in 0..4096{if decoder.terminal_is_empty(){break}let demand=decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;crate::close_original_retained_step(cx,demand,|grant|decoder.close_step(grant))?;}assert!(decoder.terminal_is_empty());Ok(())}).unwrap();assert!(input.is_none());caller.retire(stock);
}
